#!/usr/bin/env bash
#用到哪，学到哪。
#bash <(curl -sSL https://get.docker.com)；安装docker
#export PATH="/目录/文件:$PATH"；ln -s ${文件} /usr/local/bin；终端输入进程/脚本名称可直接运行
#vim按下i进入编辑模式；按下ecs退出编辑模式；输入:wq!强制保存退出；输入:q!退出不保存
#iptables -A INPUT -p tcp --dport 端口 -j ACCEPT
#ps -ef | grep 进程 | grep -v grep | awk '{print $2}'；查找进程ID
#awk -F '"' '{print $4}' | cut -c 2-；以"为分隔号；-c 2显示第二个字符；-c 2-从第二个字符开始显示
#awk -F '.' 'NR==1 {print $NF}'；以.为分隔号；打印第一行第四列；$NF打印最后一列
#awk -F '[. (]' '{print $2$3}'；分别以.空格(为分隔号；$2$3无分隔号；打印23；$2,$3；打印2 3；$2"|"$3；打印2|3
#awk中/ /是正则表达式；^表示字符串中开始的位置；d/-分别是权限中开始字符
#ls -l /目录 | awk '/^d/ {print $NF}'；打印/目录下的子目录
#ls -l /目录 | awk '/^-/ {print $NF}'；打印/目录下的文件
#sed -i 's|/目录/文件|替换|g; s#目录/文件#替换#g' /目录/文件；含有路径时；分隔符需要把/换成|
#sed -i "s/目标/$替换/g" /目录/文件；引用变量需要把'换成"或'"$替换"'
#sed -i '$a '"$变量"'\n文本' /目录/文件；在最后一行$a插入；引用变量需要'"$"'
#echo -e "文本\n换行\n" > /目录/文件；不存在则创建；存在则覆盖
#base64 -w 0 HTML.tar.gz > HTML.txt；base64编码
#base64 -d HTML.txt > HTML.tar.gz；base64解码
#cd /文件目录；tar -zcvf 文件.tar.gz 文件
#tar -xzvf /目录/文件.tar.gz -C /解压指定目录
#cat > file << EOF；覆盖&转义(文本中不需要转义的特殊符号前加\)
#cat >> file << 'EOF'；追加&禁止转义(开头EOF加上''即可)
# ！(非、不是)；
#if [ -s "文件" ]；目录/文件存在且size大于0
#if [ -d "目录" ]；目录存在
#if [ -f "文件" ]；文件存在
#if [ -z "$str" ]；变量长度为0
#if [ -n "$str" ]；变量非空
#if ! type "nginx" ; then 安装; fi；如果命令不存在则安装
#if grep -qi "$str" /etc/文件 || grep -qi "$str" /var/文件 ; then 当无判断函数；只检测命令时；无需使用括号；记得加空格
#-f/-gt等判断函数需要用[]；有多个连接符号||并存在[]；最外层需要用{}；记得加空格
#if [[ -f "文件" && -n "$(cat /文件)" ]]; then 多个-f/-gt等判断函数且有连接符号&&；只需在最外层使用[[]]
#if { [ -d "目录" ] && grep -qi "$str" /目录; } || { [ -f "文件" ] && grep -qi "$str" /目录; }; then 如果目录存在并检索到变量或者文件存在并检索到变量；在括号中的命令结尾要加;分号
#$(grep "名称" /目录 2>&1 | awk)；目录文件不存在时，脚本不会提示错误，变量为空
#命令 >/dev/null 2>&1；命令成功或失败都不会显示
#set -ue(退出报错)；set -x(显示命令)

set -u
red(){  echo -e "\e[31m$1\e[0m";}
blue(){  echo -e "\e[34m$1\e[0m";}
purple(){  echo -e "\e[35m$1\e[0m";}
cyan(){  echo -e "\e[36m$1\e[0m";}
readp(){  read -p "$(cyan "$1")" $2;}

HTML(){
  blue "解压html。"
  echo "" | base64 -d | tee HTML.tar.gz > /dev/null
  tar -xzvf HTML.tar.gz -C /etc/nginx
}

HTTP(){
  if [ ! -d "/etc/nginx/HTML" ]; then
    HTML
    cat > /etc/nginx/nginx.conf << 'HTTP'
pid #/nginx.pid;
worker_processes auto;
error_log /dev/null; #/var/log/nginx/error.log;
events {
  multi_accept on;
  worker_connections 1024;
}
http {
  include mime.types;
  default_type application/octet-stream;
  map $http_x_forwarded_for $client_ip {
    "" $remote_addr;
    "~*(?P<firstAddr>([0-9a-f]{0,4}:){1,7}[0-9a-f]{1,4}|([0-9]{1,3}\.){3}[0-9]{1,3})$" $firstAddr;
  } #创建自定义变量 $client_ip 实现 CDN 获取到客户端真实 IP
  log_format main '$client_ip - $remote_user [$time_local] "$request"'
                  '$status $body_bytes_sent "$http_referer"'
                  '"$http_user_agent" "$http_x_forwarded_for"';
  #access_log off; #/var/log/nginx/access.log main;
  sendfile on;
  server_tokens off;
  keepalive_timeout 65;
  ssl_prefer_server_ciphers on;
  ssl_protocols TLSv1.2 TLSv1.3;
  ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
  include #/etc/nginx;
}
HTTP
    sed -i "s|#/nginx.pid|${nginxpid}|g; s|#/etc/nginx|${nginxconfig}|g" /etc/nginx/nginx.conf
  fi
}

DEST(){
  if [ -z "$(cat $serverconfig 2>/dev/null)" ]; then REALITY; fi
  cat > $nginxconfig << DEST
server {
  listen 80;
  listen [::]:80;
  return 301 https://\$host\$request_uri;
}
server {
  listen 127.0.0.1:44380 default_server proxy_protocol $nginxhttp
  set_real_ip_from 127.0.0.1;
  real_ip_header proxy_protocol;
  ssl_protocols TLSv1.2 TLSv1.3;
  ssl_reject_handshake on;
} #限定域名连接，禁止其他方式访问网站
server {
  listen 127.0.0.1:44380 proxy_protocol $nginxhttp
  set_real_ip_from 127.0.0.1;
  real_ip_header proxy_protocol;
  server_name cdn$serverdomain; #修改 CDN 域名
  ssl_certificate ${servercertpath}/${serverdomain}/fullchain.pem; #修改 CDN 域名证书
  ssl_certificate_key ${servercertpath}/${serverdomain}/privkey.pem; #修改 CDN 域名证书
  location /$(grep '"id"' $serverconfig | awk -F '"' 'NR==1 {print $4}') { #与 reality-xhttp 中 path 对应
    grpc_pass grpc://127.0.0.1:44308; #转发 reality-xhttp 监听进程
    grpc_set_header Host \$host;
    grpc_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
  }
  location / {
    root /etc/nginx/HTML;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
  }
}
server {
  #listen 443 reuseport quic;#版本不小于 v1.25.0 且 SSL 库支持 QUIC
  #listen [::]:443 reuseport quic;#版本不小于 v1.25.0 且 SSL 库支持 QUIC
  listen 127.0.0.1:44380 proxy_protocol $nginxhttp
  set_real_ip_from 127.0.0.1;
  real_ip_header proxy_protocol;
  server_name $serverdomain;
  ssl_certificate ${servercertpath}/${serverdomain}/fullchain.pem;
  ssl_certificate_key ${servercertpath}/${serverdomain}/privkey.pem;
  location /$(grep '"id"' $serverconfig | awk -F '"' 'NR==1 {print $4}') { #与 reality-xhttp 中 path 对应
    grpc_pass grpc://127.0.0.1:44308; #转发 reality-xhttp 监听进程
    grpc_set_header Host \$host;
    grpc_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
  }
  location / {
    root /etc/nginx/HTML;
    add_header Alt-Svc 'h3=":443"; ma=86400'; #通告 HTTP/3 server 的可用性
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
  }
  location ~ ^/surl/(xlink|mlink)/(.*) {
    default_type 'text/plain; charset=utf-8';
    alias ${serversubpath}/\$1/\$2;
  }
  location /cgi-bin/gettoken {
    proxy_pass https://qyapi.weixin.qq.com;
  }
  location /cgi-bin/message/send {
    proxy_pass https://qyapi.weixin.qq.com;
  }
  location /cgi-bin/menu/create {
    proxy_pass https://qyapi.weixin.qq.com;
  }
  location /lk/ {
    proxy_pass http://127.0.0.1:16601/$(grep '"id"' $serverconfig | awk -F '"' 'NR==1 {print $4}')/;
  }
  location /mp/ {
    proxy_pass http://127.0.0.1:3000/;
  }
  location /jf/ {
    proxy_pass http://127.0.0.1:8096/;
  }
}
#1、reality+vision 和 reality+xhttp 客户端仅使用 www.example.com 域名连接。
#2、xhttp+tls 客户端可使用 www.example.com 或 cdn.example.com 域名连接。
DEST
  pkill -9 nginx; service nginx restart; purple "Nginx配置完成！"
}

REALITY(){
  if [ -z "$serverdomain" ]; then CERT; fi
  serverx25519="$(xray x25519)"
  serveruuid="$(xray uuid)"
  serversid="$(RANDOMSID)"
  cat > $serverconfig << REALITY
{
  "routing": {
    "domainStrategy": "AsIs",
    "rules": [
      {
        "domain": ["geosite:category-ads-all"],
        "outboundTag": "block"
      },
      {
        "ip": ["geoip:private", "geoip:cn"],
        "outboundTag": "direct"
      },
      {
        "protocol": ["bittorrent"],
        "outboundTag": "direct"
      },
      {
        "user": ["xray@reality.xtls"],
        "outboundTag": "reverse"
      }
    ]
  },
  "inbounds": [
    {
      "tag": "vision",
      "port": 443,
      "protocol": "vless",
      "settings": {
        "users": [
          {
            "id": "$serveruuid",
            "flow": "xtls-rprx-vision",
            "reverse": {
              "tag": "reverse"
            }
          },
          {
            "id": "$serveruuid",
            "flow": "xtls-rprx-vision",
            "email": "xray@reality.xtls"
            }
          }
        ],
        "decryption": "none",
        "fallbacks": [
          {
            "dest": 44308 // 回落 reality-xhttp 监听进程
          }
        ]
      },
      "streamSettings": {
        "network": "raw",
        "security": "reality",
        "realitySettings": {
          "target": 44380, // 转发 Nginx 监听进程
          "xver": 1,
          "serverNames": ["$serverdomain"],
          "privateKey": "$(echo "$serverx25519" | grep "PrivateKey" | awk -F ': ' '{print $2}')",
          "publicKey": "$(echo "$serverx25519" | grep "Password" | awk -F ': ' '{print $2}')",
          "shortIds": ["$serversid"]
        }
      },
      "sniffing": {
        "enabled": true,
        "destOverride": ["http", "tls", "quic"],
        "routeOnly": true
      }
    },
    {
      "tag": "xhttp",
      "listen": "127.0.0.1",
      "port": 44308,
      "protocol": "vless",
      "settings": {
        "users": [
          {
            "id": "$serveruuid"
          }
        ],
        "decryption": "none"
      },
      "streamSettings": {
        "network": "xhttp",
        "xhttpSettings": {
          "host": "", // 服务端不验证 host 客户端玩法更多
          "mode": "auto", // 服务端设置 auto 客户端玩法更多
          "path": "/${serveruuid}"
        }
      },
      "sniffing": {
        "enabled": true,
        "destOverride": ["http", "tls", "quic"],
        "routeOnly": true
      }
    },
    {
      "tag": "hy2",
      "port": 443,
      "protocol": "hysteria",
      "settings": {
        "version": 2,
        "users": [
          {
            "auth": "$serveruuid"
          }
        ]
      },
      "streamSettings": {
        "network": "hysteria",
        "hysteriaSettings": {
          "version": 2,
          "auth": "$serveruuid",
          "udpIdleTimeout": 60,
          "masquerade": {
            "type": "proxy",
            "url": "https://${serverdomain}",
            "rewriteHost": true,
            "insecure": false
          }
        },
        "security": "tls",
        "tlsSettings": {
          "alpn": ["h3"],
          "certificates": [
            {
              "certificateFile": "${servercertpath}/${serverdomain}/fullchain.pem",
              "keyFile": "${servercertpath}/${serverdomain}/privkey.pem"
            }
          ]
        },
        "finalmask": {
          "quicParams": {
            "congestion": "brutal",
            "brutalDown": "50 mbps", // 服务端的下载是客户端的上传
            "brutalUp": "150 mbps" // 服务端的上传是客户端的下载
          }
        }
      },
      "sniffing": {
        "enabled": true,
        "destOverride": ["http", "tls", "quic"],
        "routeOnly": true
      }
    }
  ],
  "outbounds": [
    {
      "protocol": "freedom",
      "tag": "direct"
    },
    {
      "protocol": "blackhole",
      "tag": "block"
    }
  ],
  "policy": {
    "levels": {
      "0": {
        "statsUserUplink": true,
        "statsUserDownlink": true
      }
    }
  }
}
#1、reality+vision 和 reality+xhttp 客户端仅使用 www.example.com 域名连接。
#2、xhttp+tls 客户端可使用 www.example.com 或 cdn.example.com 域名连接。
REALITY
  service $servername restart; purple "Xray配置完成！"
}

RCINITD(){
  serversystem="/etc/init.d/${servername}"
  serverenable="rc-update add $servername"
  nginxpid="/run/nginx/nginx.pid"
  nginxconfig="/etc/nginx/http.d/default.conf"
  qrcmd="qr --ascii"

  if ! type "nginx" "certbot" "unzip" "tar" "qr" "ufw" >/dev/null 2>&1; then
    blue "开始安装。"
    apk update && apk upgrade && apk add nginx certbot certbot-nginx unzip tar py3-qrcode ufw
  fi

  sleep 1

  if [ ! -f "$serversystem" ]; then
    DOWNLOAD
    cat > $serversystem << RCINITD
#!/sbin/openrc-run
name="$servername"
description="$servername Service"
supervisor=supervise-daemon
respawn_delay=5
respawn_max=2
respawn_period=600
pidfile="/run/\${RC_SVCNAME}.pid"
rc_ulimit="-u 10240 -n 102400"
capabilities="^cap_net_bind_service,^cap_net_admin,^cap_net_raw"
confdir=${confdir:-"$serverpath"}
command="$serverprocess"
command_args="run -confdir \$confdir"
required_files="\$confdir"
depend() {
  need net
  want dns
  after firewall
}
RCINITD
    chmod +x $serversystem && $serverenable && purple "Service配置完成！"
  fi
}

SYSTEMD(){
  serversystem="/etc/systemd/system/${servername}.service"
  serverenable="systemctl enable $servername"
  nginxpid="/run/nginx.pid"
  nginxconfig="/etc/nginx/sites-available/default"
  qrcmd="qrencode -m 1 -t UTF8i"

  if ! type "nginx" "certbot" "unzip" "tar" "qrencode" "ufw" >/dev/null 2>&1; then
    blue "开始安装。"
    apt update && apt upgrade && apt install -y nginx certbot python3-certbot-nginx unzip tar qrencode ufw
  fi

  sleep 1

  if [ ! -f "$serversystem" ]; then
    DOWNLOAD
    cat > $serversystem << SYSTEMD
[Unit]
Description=$servername Service
After=network.target nss-lookup.target
[Service]
ExecStart=$serverprocess run -confdir $serverpath
Restart=on-failure
RestartPreventExitStatus=23
LimitNPROC=10240
LimitNOFILE=102400
RuntimeDirectory=$servername
RuntimeDirectoryMode=0755
[Install]
WantedBy=multi-user.target
SYSTEMD
    chmod 644 $serversystem && $serverenable && purple "Service配置完成！"
  fi
}

DOWNLOAD(){
  while true; do
    while true; do
      blue "$serverurl，正在下载。"
      curl -O -L -H 'Cache-Control: no-cache' $serverurl -#
      if unzip -t $serverfile; then
        break
      else
        sleep 15
        servertag=""
        servertag="$(curl -sf $serverapi | grep '"tag_name"' | awk -F '"' '{print $4}')"
        serverurl="${serversite}/${servertag}/${serverfile}"
      fi
    done
    blue "$serverurl.dgst，正在下载。"
    curl -O -L -H 'Cache-Control: no-cache' $serverurl.dgst -#
    serverzip="$(sha256sum $serverfile | awk '{printf $1}')"
    serverdgst="$(awk -F '= ' '/256=/ {print $2}' $serverfile.dgst)"
    if [ "$serverdgst" == "$serverzip" ]; then
      blue "check！"
      mkdir -p -m 644 $serverpath
      unzip -oj $serverfile -d $serverpath
      rm -rf $serverfile
      rm -rf $serverfile.dgst
      ln -sf ${serverpath}/${servername} /usr/local/bin
      break
    fi
  done
  if [ -f "$serversystem" ]; then service $servername restart; fi
}

DOMAIN(){
  readp "请输入域名：" serverdomain
  purple "域名：$serverdomain"
  while true; do
    readp "请确认域名[yes/no]：" input
    case "$input" in
      [yY][eE][sS]|[yY]) purple "已确认。"; break;;
      [nN][oO]|[nN]) readp "请输入域名：" serverdomain;;
      *) red "请重新输入！"; continue;;
    esac
  done
}

CERT(){
  HTTP
  if [ -d "${servercertpath}/${serverdomain}" ]; then
    blue "续签SSL证书。"
    certbot renew --deploy-hook 'service nginx restart'
  else
    blue "申请SSL证书。"
    rm -rf /etc/letsencrypt/{archive,live,renewal}
    echo -e "0 0 1 * * certbot renew --deploy-hook 'service nginx restart'" > /var/spool/cron/crontabs/root
    echo -e "server {\n    listen 80;\n    listen [::]:80;\n    server_name $serverdomain;\n}" > $nginxconfig
    service nginx restart && certbot --nginx --agree-tos -n -m ssl@cert.bot -d $serverdomain && REALITY && DEST
  fi
}

RANDOMSID(){
  local chars="123456789abcdef"
  local shortid=""
  while [ "${#shortid}" -lt "12" ]; do
    randomid="${chars:$RANDOM%${#chars}:1}"
    shortid="$shortid$randomid"
  done
  echo "$shortid"
}

TOKEN(){
  if [ -z "$serveruser" ]; then
    readp "请输入user：" serveruser
    purple "$serveruser"
    while true; do
      readp "请确认[Yes/No]：" input
      case $input in
        [yY][eE][sS]|[yY]) purple "已确认。"; break;;
        [nN][oO]|[nN]) readp "请输入user：" serveruser;;
        *) red "请重新输入！"; continue;;
      esac
    done
  fi
  if [ -z "$serversalt" ]; then
    readp "请输入salt：" serversalt
    purple "$serversalt"
    while true; do
      readp "请确认[Yes/No]：" input
      case $input in
        [yY][eE][sS]|[yY]) purple "已确认。"; break;;
        [nN][oO]|[nN]) readp "请输入salt：" serversalt;;
        *) red "请重新输入！"; continue;;
      esac
    done
  fi
  if [ -z "$(cat ${serversubpath}/${serveruser} 2>/dev/null)" ]; then
    mkdir -p -m 555 ${serversubpath}/local
    mkdir -p -m 555 ${serversubpath}/xlink
    mkdir -p -m 555 ${serversubpath}/mlink
    echo "$serversalt" > ${serversubpath}/${serveruser}
  fi
}

SUBSCRIBE(){
  if [ -z "$(cat $serverconfig 2>/dev/null)" ]; then REALITY; DEST; fi
  xdomain="$(grep '"serverNames"' $serverconfig | awk -F '"' '{print $4}')"
  xuuid="$(grep '"id"' $serverconfig | awk -F '"' 'NR==1 {print $4}')"
  xrpk="$(grep '"publicKey"' $serverconfig | awk -F '"' '{print $4}')"
  xsid="$(grep '"shortIds"' $serverconfig | awk -F '"' '{print $4}')"
  cat > ${serversubpath}/local/xray << XSUB
vless://${xuuid}@${xdomain}:443?type=tcp&flow=xtls-rprx-vision&tls=true&security=reality&sni=${xdomain}&pbk=${xrpk}&sid=${xsid}&fp=chrome#${serveruser}-vision
vless://${xuuid}@${xdomain}:443?type=xhttp&path=/${xuuid}&mode=auto&tls=true&security=reality&sni=${xdomain}&pbk=${xrpk}&sid=${xsid}&fp=chrome#${serveruser}-xhttp
hysteria2://${xuuid}@${xdomain}:443?sni=${xdomain}&alpn=h3&insecure=0&downmbps=150#${serveruser}-hy2
XSUB
  cat > ${serversubpath}/local/mihomo << MSUB
proxies:
  - name: "${serveruser}-vision"
    type: vless
    server: $xdomain
    port: 443
    uuid: $xuuid
    network: tcp
    flow: xtls-rprx-vision
    reality-opts:
      public-key: $xrpk
      short-id: $xsid
    tls: true
    sni: $xdomain
    skip-cert-verify: false
    client-fingerprint: chrome
    udp: true
    packet-encoding: xudp
  - name: "${serveruser}-xhttp"
    type: vless
    server: $xdomain
    port: 443
    uuid: $xuuid
    network: xhttp
    obfs: xhttp
    xhttp-opts:
      path: /$xuuid
      mode: auto
    reality-opts:
      public-key: $xrpk
      short-id: $xsid
    tls: true
    sni: $xdomain
    skip-cert-verify: false
    client-fingerprint: chrome
    udp: true
    packet-encoding: xudp
  - name: "${serveruser}-hy2"
    type: hysteria2
    server: $xdomain
    port: 443
    password: $xuuid
    downmbps: 150
    sni: $xdomain
    alpn: h3
    skip-cert-verify: false
MSUB
  rm -rf ${serversubpath}/xlink/*
  rm -rf ${serversubpath}/mlink/*
  serverlocation="$(echo -n "${serversalt}": | md5sum | awk '{print $1}')"
  echo -e "$(base64 -w 0 ${serversubpath}/local/xray)" > ${serversubpath}/xlink/${serverlocation}
  cat ${serversubpath}/local/mihomo > ${serversubpath}/mlink/${serverlocation}
  chmod -R 555 $serversubpath
  subxlink="https://${serverdomain}/surl/xlink/${serverlocation}"#$serveruser
  submlink="https://${serverdomain}/surl/mlink/${serverlocation}"#$serveruser
  blue "\nXray\n"; purple "$subxlink\n"; $qrcmd "$subxlink"; blue "\nMihomo\n"; purple "$submlink\n"; $qrcmd "$submlink"
}

SSHD(){
  if [ ! -f /etc/ssh/sshd_config.d/sshd.conf ]; then
    readp "请输入SSH端口：" serversshd
    purple "SSH端口：$serversshd"
    echo -e "PermitRootLogin yes\nPubkeyAuthentication yes\nPasswordAuthentication no\nPort $serversshd" > /etc/ssh/sshd_config.d/sshd.conf
    service ssh restart
    if [ -f /usr/lib/systemd/system/ssh.socket ]; then sed -i "s/22/$serversshd/g" /usr/lib/systemd/system/ssh.socket && systemctl restart ssh.socket; fi
    ufw allow $serversshd; ufw allow 80/tcp; ufw allow 80/udp; ufw allow 443/tcp; ufw allow 443/udp; ufw allow 23710/tcp; ufw allow 23710/udp; echo "y" | ufw enable >/dev/null
  fi
}

CHECK(){
  if { [ -f "/etc/issue" ] && grep -qi "Alpine" /etc/issue; } || { [ -f "/etc/os-release" ] && grep -qi "ID=alpine" /etc/os-release; }; then
    release="alpine"
    RCINITD
  elif { [ -f "/etc/issue" ] && grep -qi "debian" /etc/issue; } || { [ -f "/etc/os-release" ] && grep -qi "ID=debian" /etc/os-release; }; then
    release="debian"
    SYSTEMD
  elif { [ -f "/etc/issue" ] && grep -qi "Ubuntu" /etc/issue; } || { [ -f "/etc/os-release" ] && grep -qi "ID=ubuntu" /etc/os-release; }; then
    release="ubuntu"
    SYSTEMD
  else
    red "未知架构！"
    exit 0
  fi

  if [ "$(nginx -v 2>&1 | awk -F '[.(]' '{print $2$3}')" -ge 251 ]; then
    nginxhttp="ssl;http2 on;"
  else
    nginxhttp="ssl http2;"
  fi

  if grep -q "tcp_bbr" /proc/modules; then
    if [ ! -f /etc/modules-load.d/bbr.conf ]; then
      echo "tcp_bbr" > /etc/modules-load.d/bbr.conf
      if sysctl -w net.ipv4.tcp_congestion_control=bbr >/dev/null 2>&1; then
        echo "net.ipv4.tcp_congestion_control=bbr" > /etc/sysctl.d/bbr.conf
      fi
      if sysctl -w net.core.default_qdisc=fq >/dev/null 2>&1; then
        echo "net.core.default_qdisc=fq" >> /etc/sysctl.d/bbr.conf
      fi
      sysctl -p /etc/sysctl.d/bbr.conf
    fi
  fi

  if [ ! -f "$serverprocess" ]; then DOWNLOAD; fi

  if [ -z "$serverdomain" ]; then HTTP; DOMAIN; CERT; fi
}

Nginx(){
  while true; do
    purple "\n检测到"$(ls -l $servercertpath 2>&1 | awk '/^d/ {print $NF}')"证书。\n"
    blue "1、续签证书"
    blue "2、更改域名"
    blue "3、退出"
    purple ""
    readp "请输入选项：" option
    case "$option" in
      1) CERT; return;;
      2) DOMAIN; CERT; return;;
      3) return;;
      *) red "请重新输入！"; continue;;
    esac
  done
}

Xray(){
  while true; do
    purple "\n检测到"$(xray version | awk 'NR==1 {print $2}')"版本。\n"
    blue "1、升级内核"
    blue "2、订阅链接"
    blue "3、退出"
    purple ""
    readp "请输入选项：" option
    case "$option" in
      1) DOWNLOAD; return;;
      2) TOKEN; SUBSCRIBE; return;;
      3) return;;
      *) red "请重新输入！"; continue;;
    esac
  done
}

MENU(){
  while true; do
    purple ""
    blue "1、Xray"
    blue "2、Nginx"
    blue "3、Exit"
    purple ""
    readp "请输入选项：" option
    case "$option" in
      1) Xray; continue;;
      2) Nginx; continue;;
      3) break;;
      *) red "请重新输入！"; continue;;
    esac
  done
}

case "$(uname -m)" in
  amd64 | x86_64) serverfile="Xray-linux-64.zip";;
  armv8 | aarch64) serverfile="Xray-linux-arm64-v8a.zip";;
  i386 | i686) serverfile="Xray-linux-32.zip";;
  *) red "未知架构！"; exit 0;;
esac

servername="xray"
serversubpath="/etc/allone/subscribe"
servercertpath="/etc/letsencrypt/live"
serverpath="/etc/allone/${servername}"
serverconfig="${serverpath}/config.json"
serverprocess="${serverpath}/${servername}"
serveruser="$(ls -l $serversubpath 2>&1 | awk '/^-/ {print $NF}')"
serversalt="$(cat ${serversubpath}/${serveruser} >/dev/null 2>&1)"
serverdomain="$(ls -l $servercertpath 2>&1 | awk '/^d/ {print $NF}')"
serversite="https://github.com/XTLS/Xray-core/releases/download"
serverapi="https://api.github.com/repos/XTLS/Xray-core/releases/latest"
servertag="$(curl -sf "$serverapi" | grep '"tag_name"' | awk -F '"' '{print $4}')"
serverurl="${serversite}/${servertag}/${serverfile}"

purple "Mu"
CHECK
MENU
SSHD
purple "End!"
